const { spawn } = require("child_process");
const http = require("http");
const path = require("path");

async function main() {
  const cdpPort = 9347;
  const chrome = spawn("google-chrome-stable", [
    "--headless=new",
    `--remote-debugging-port=${cdpPort}`,
    "file://" + path.resolve("app/index.html")
  ]);
  await new Promise(r => setTimeout(r, 800));
  const targets = await new Promise(res => http.get(`http://127.0.0.1:${cdpPort}/json/list`, r => {
    let d = ""; r.on("data", c => d += c); r.on("end", () => res(JSON.parse(d)));
  }));
  const ws = new WebSocket(targets[0].webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);
  let id = 1;
  const evalCdp = (expr) => new Promise(res => {
    const myId = id++;
    ws.addEventListener("message", function h(e) {
      const m = JSON.parse(e.data);
      if (m.id === myId) { ws.removeEventListener("message", h); res(m.result.result.value); }
    });
    ws.send(JSON.stringify({ id: myId, method: "Runtime.evaluate", params: { expression: expr, returnByValue: true } }));
  });
  const res = await evalCdp(`(() => {
    const key = document.querySelector(".tv-keyboard-container .key-btn[data-key=\"Q\"]");
    key.classList.add("focused");
    const matchedRules = [];
    for (const sheet of document.styleSheets) {
      try {
        for (const rule of sheet.cssRules) {
          if (rule.selectorText && key.matches(rule.selectorText)) {
            matchedRules.push({
              href: sheet.href ? sheet.href.split("/").pop() : "inline",
              selector: rule.selectorText,
              cssText: rule.cssText
            });
          }
        }
      } catch (e) {}
    }
    const computed = window.getComputedStyle(key);
    return {
      matchedRules,
      boxShadow: computed.boxShadow,
      backgroundColor: computed.backgroundColor
    };
  })()`);
  console.log(JSON.stringify(res, null, 2));
  chrome.kill();
}
main();
