"const { spawn } = require('child_process');
const http = require('http');
const path = require('path');

async function main() {
  const cdpPort = 9349;
  const chrome = spawn('google-chrome-stable', [
    '--headless=new',
    `--remote-debugging-port=${cdpPort}`,
    'file://' + path.resolve(__dirname, '../app/index.html')
  ]);
  await new Promise(r => setTimeout(r, 800));
  const targets = await new Promise(res => http.get(`http://127.0.0.1:${cdpPort}/json/list`, r => {
    let d = ''; r.on('data', c => d += c); r.on('end', () => res(JSON.parse(d)));
  }));
  const ws = new WebSocket(targets[0].webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);
  let id = 1;
  const evalCdp = (expr) => new Promise((resolve, reject) => {
    const myId = id++;
    ws.addEventListener('message', function h(e) {
      const m = JSON.parse(e.data);
      if (m.id === myId) {
        ws.removeEventListener('message', h);
        if (m.error) reject(m.error);
        else if (m.result.exceptionDetails) reject(m.result.exceptionDetails);
        else resolve(m.result.result.value);
      }
    });
    ws.send(JSON.stringify({ id: myId, method: 'Runtime.evaluate', params: { expression: expr, returnByValue: true } }));
  });

  const res = await evalCdp(`(() => {
    document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
    document.getElementById('view-search').classList.add('active');

    const key = document.querySelector('.tv-keyboard-container .key-btn[data-key="Q"]');
    key.classList.add('focused');
    const s = window.getComputedStyle(key);
    return {
      classes: key.className,
      boxShadow: s.boxShadow,
      backgroundColor: s.backgroundColor,
      borderColor: s.borderColor,
      transform: s.transform,
      outline: s.outline
    };
  })()`);
  console.log('KEY FOCUS STYLE:', res);
  chrome.kill();
  process.exit(0);
}

main().catch(e => { console.error(e); process.exit(1); });
"

