const http = require('http');
const path = require('path');
const fs = require('fs');

async function main() {
  const cdpPort = 9349;
  const userDataDir = `/tmp/chrome-test-${Date.now()}`;
  const appHtmlPath = path.resolve(__dirname, '../app/index.html');
  const appFileUrl = `file://${appHtmlPath}`;

  const chrome = spawn('google-chrome-stable', [
    '--headless=new',
    `--remote-debugging-port=${cdpPort}`,
    `--user-data-dir=${userDataDir}`,
    '--no-sandbox',
    '--disable-gpu',
    '--window-size=1920,1080',
    appFileUrl
  ]);
  await new Promise(r => setTimeout(r, 1000));
  const targets = await new Promise(res => http.get(`http://127.0.0.1:${cdpPort}/json/list`, r => {
    let d = ''; r.on('data', c => d += c); r.on('end', () => res(JSON.parse(d)));
  }));

  const pageTarget = targets.find(t => t.type === 'page' && t.url.includes('index.html'));
  const ws = new WebSocket(pageTarget.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);
  let id = 1;
  const evalCdp = (expr) => new Promise((resolve, reject) => {
    const myId = id++;
    ws.addEventListener('message', function h(e) {
      const m = JSON.parse(e.data);
      if (m.id === myId) {
        ws.removeEventListener('message', h);
        if (m.error) reject(m.error);
