"  // Keyboard High-Contrast Focus State Verification
  const focusKeyData = await evaluate(`(() => {
    const key = document.querySelector('.tv-keyboard-container .key-btn[data-key="Q"]');
    key.style.setProperty('transition', 'none', 'important');
    key.classList.add('focused');
    const s = window.getComputedStyle(key);
    const rect = key.getBoundingClientRect();
    const result = {
      bgColor: s.backgroundColor,
      color: s.color,
      borderColor: s.borderColor,
      transform: s.transform,
      boxShadow: s.boxShadow,
      width: rect.width,
      height: rect.height
    };
    key.classList.remove('focused');
    key.style.removeProperty('transition');
    return result;
  })()`);"

